// static
bool UsbHostInstanceStubDispatch::AcceptWithResponder(
    UsbHostInstance* impl,
    mojo::Message* message,
    std::unique_ptr<mojo::MessageReceiverWithStatus> responder) {
  [[maybe_unused]] const bool message_is_sync =
      message->has_flag(mojo::Message::kFlagIsSync);
  [[maybe_unused]] const uint64_t request_id = message->request_id();
  switch (message->header()->name) {
    case internal::kUsbHostInstance_Init_Name: {

      internal::UsbHostInstance_Init_Params_Data* params =
          reinterpret_cast<
              internal::UsbHostInstance_Init_Params_Data*>(
                  message->mutable_payload());
      
      
      // Validation for UsbHostInstance.0
      bool success = true;
      ::mojo::PendingRemote<UsbHostHost> p_host_remote{};
      UsbHostInstance_Init_ParamsDataView input_data_view(params, message);
      
      if (success) {
        p_host_remote =
            input_data_view.TakeHostRemote<decltype(p_host_remote)>();
      }
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            UsbHostInstance::Name_, 0, false);
        return false;
      }
      UsbHostInstance::InitCallback callback =
          UsbHostInstance_Init_ProxyToResponder::CreateCallback(
              *message, std::move(responder));
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->Init(        
        std::move(p_host_remote), std::move(callback));
      return true;
    }
    case internal::kUsbHostInstance_OnDeviceAdded_Name: {
      break;
    }
    case internal::kUsbHostInstance_OnDeviceRemoved_Name: {
      break;
    }
  }
  return false;
}
