void UsbHostHostAsyncWaiter::OpenDevice(
    const std::string& guid, const std::optional<std::string>& pkg_name, ::mojo::ScopedHandle* out_usb_fd) {
  base::RunLoop loop;
  proxy_->OpenDevice(std::move(guid),std::move(pkg_name),
      base::BindOnce(
          [](base::RunLoop* loop,
             ::mojo::ScopedHandle* out_usb_fd
,
             ::mojo::ScopedHandle usb_fd) {*out_usb_fd = std::move(usb_fd);
            loop->Quit();
          },
          &loop,
          out_usb_fd));
  loop.Run();
}

::mojo::ScopedHandle UsbHostHostAsyncWaiter::OpenDevice(
    const std::string& guid, const std::optional<std::string>& pkg_name) {
  ::mojo::ScopedHandle async_wait_result;
  OpenDevice(std::move(guid),std::move(pkg_name),&async_wait_result);
  return async_wait_result;
}

void UsbHostHostAsyncWaiter::GetDeviceInfo(
    const std::string& guid, std::string* out_device_name, ::device::mojom::UsbDeviceInfoPtr* out_info) {
  base::RunLoop loop;
  proxy_->GetDeviceInfo(std::move(guid),
      base::BindOnce(
          [](base::RunLoop* loop,
             std::string* out_device_name
,
             ::device::mojom::UsbDeviceInfoPtr* out_info
,
             const std::string& device_name,
             ::device::mojom::UsbDeviceInfoPtr info) {*out_device_name = std::move(device_name);*out_info = std::move(info);
            loop->Quit();
          },
          &loop,
          out_device_name,
          out_info));
  loop.Run();
}



